import React, { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import axios from 'axios';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';
import { useCheckout } from '../context/CheckoutContext';

const Checkout3 = () => {
    const navigate = useNavigate();
    const { user } = useAuth();
    const { clearCart } = useCart();
    const { shippingData, paymentData, checkoutTotals, clearCheckout } = useCheckout();
    const [cartItems, setCartItems] = useState([]);
    const [processing, setProcessing] = useState(false);

    useEffect(() => {
        const items = JSON.parse(localStorage.getItem('bindass_cart')) || [];
        setCartItems(items);
    }, []);

    const handlePlaceOrder = async () => {
        if (!user) return alert("Please sign in.");

        setProcessing(true);
        try {
            const token = await user.getIdToken();

            // 1. Create Order on Server
            const { data: order } = await axios.post('http://localhost:5001/api/payments/create-order',
                { amount: checkoutTotals.totalAmount },
                { headers: { Authorization: `Bearer ${token}` } }
            );

            // 2. Razorpay Options
            const options = {
                key: "rzp_test_SawF4zg8SaC3gx",
                amount: order.amount,
                currency: "INR",
                name: "BINDASS!! Co.",
                description: "Luxury Collection Purchase",
                order_id: order.id,
                handler: async (response) => {
                    try {
                        // 3. Verify Payment with Full Shipping Info
                        const verifyResponse = await axios.post('http://localhost:5001/api/payments/verify-payment',
                            { 
                                ...response, 
                                orderDetails: {
                                    cart: cartItems.map(item => ({
                                        id: item._id || item.productId,
                                        name: item.name,
                                        quantity: item.quantity,
                                        price: item.price
                                    })),
                                    amount: checkoutTotals.totalAmount,
                                    shippingInfo: shippingData // PASSING FULL SHIPPING DATA FOR FULFILLMENT
                                }
                            },
                            { headers: { Authorization: `Bearer ${token}` } }
                        );

                        // 4. Success State
                        await clearCart();
                        clearCheckout();
                        navigate('/success', { 
                            state: { 
                                order: verifyResponse.data.order || { 
                                    id: response.razorpay_order_id, 
                                    amount: checkoutTotals.totalAmount,
                                    items: cartItems 
                                } 
                            } 
                        });
                    } catch (err) {
                        console.error("Order verification failed:", err);
                        alert("Payment successful but order verification failed. Support has been notified.");
                    }
                },
                prefill: {
                    name: `${shippingData.firstName} ${shippingData.lastName}`,
                    email: shippingData.email,
                    contact: shippingData.phone
                },
                theme: { color: "#10221c" },
                modal: {
                    ondismiss: () => setProcessing(false)
                }
            };

            const rzp = new window.Razorpay(options);
            rzp.open();
        } catch (error) {
            console.error("Payment initiation error:", error);
            alert("Failed to initialize payment. Please try again.");
            setProcessing(false);
        }
    };

    return (
        <div className="bg-background-light dark:bg-background-dark text-slate-900 dark:text-slate-100 font-display min-h-screen">
            <Navbar />
            <main className="max-w-7xl mx-auto px-6 py-12">
                {/* Stepper */}
                <div className="mb-12 max-w-3xl">
                    <div className="flex items-center justify-between relative">
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-primary/10 -z-10 -translate-y-1/2"></div>
                        <div className="flex items-center gap-2 bg-background-light pr-4 cursor-pointer" onClick={() => navigate('/checkout')}>
                            <div className="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold shadow-lg shadow-emerald-500/20">
                                <i className="material-icons text-sm">check</i>
                            </div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-emerald-500">Shipping</span>
                        </div>
                        <div className="flex items-center gap-2 bg-background-light px-4 cursor-pointer" onClick={() => navigate('/checkout/payment')}>
                            <div className="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold shadow-lg shadow-emerald-500/20">
                                <i className="material-icons text-sm">check</i>
                            </div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-emerald-500">Payment</span>
                        </div>
                        <div className="flex items-center gap-2 bg-background-light pl-4">
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">3</div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-primary">Review</span>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-12">
                    {/* Left Column: Final Review */}
                    <div className="flex-1 space-y-8">
                        <div>
                            <h1 className="text-3xl font-bold dark:text-black mb-2 uppercase tracking-tighter">Review Your Acquisition</h1>
                            <p className="text-slate-500 text-sm">One final glance before we process your luxury parcel.</p>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {/* Shipping Summary */}
                            <div className="bg-white p-8 rounded-xl border border-slate-100 shadow-sm relative group overflow-hidden">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full -mr-16 -mt-16 transition-transform group-hover:scale-110" />
                                <div className="flex justify-between items-center mb-6 relative">
                                    <h3 className="font-bold text-xs uppercase tracking-[0.2em] text-slate-400">Shipment Details</h3>
                                    <button onClick={() => navigate('/checkout')} className="text-primary text-[10px] font-bold uppercase tracking-widest hover:underline">Edit</button>
                                </div>
                                <p className="text-lg font-bold mb-2 uppercase tracking-tight">{shippingData.firstName} {shippingData.lastName}</p>
                                <div className="text-sm text-slate-600 space-y-1 font-medium">
                                    <p className="flex items-center gap-2"><i className="material-icons text-xs opacity-40">location_on</i> {shippingData.addressLine1}</p>
                                    <p className="pl-5">{shippingData.city}, {shippingData.pincode}</p>
                                    <p className="pl-5">{shippingData.countryCode === 'IN' ? 'India' : 'International'}</p>
                                    <p className="pt-4 flex items-center gap-2 border-t mt-4 border-slate-50"><i className="material-icons text-xs opacity-40">phone</i> {shippingData.phone}</p>
                                </div>
                            </div>

                            {/* Payment Summary */}
                            <div className="bg-white p-8 rounded-xl border border-slate-100 shadow-sm relative group overflow-hidden">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-50 rounded-full -mr-16 -mt-16 transition-transform group-hover:scale-110" />
                                <div className="flex justify-between items-center mb-6 relative">
                                    <h3 className="font-bold text-xs uppercase tracking-[0.2em] text-slate-400">Payment Selection</h3>
                                    <button onClick={() => navigate('/checkout/payment')} className="text-primary text-[10px] font-bold uppercase tracking-widest hover:underline">Edit</button>
                                </div>
                                <div className="flex items-center gap-4 mb-6">
                                    <div className="p-3 bg-emerald-50 text-emerald-600 rounded-lg">
                                        <i className="material-icons text-2xl">
                                            {paymentData.method === 'card' ? 'credit_card' : paymentData.method === 'upi' ? 'qr_code_2' : 'account_balance'}
                                        </i>
                                    </div>
                                    <div>
                                        <p className="font-bold text-sm uppercase tracking-tight">{paymentData.method || 'Selection Pending'}</p>
                                        <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">Authorized via Razorpay</p>
                                    </div>
                                </div>
                                <p className="text-[10px] text-slate-400 font-medium italic border-t pt-4 border-slate-50">You will be redirected to the secure payment portal upon clicking "Place Order".</p>
                            </div>
                        </div>

                        {/* Item Review Table */}
                        <div className="bg-white rounded-xl border border-slate-100 overflow-hidden shadow-sm">
                            <div className="px-8 py-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
                                <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-[#10221c]">Selected Pieces ({cartItems.length})</h3>
                                <Link to="/cart" className="text-primary text-[10px] font-bold uppercase tracking-widest hover:underline">Modify Bag</Link>
                            </div>
                            <div className="divide-y divide-slate-50">
                                {cartItems.map((item, idx) => (
                                    <div key={idx} className="px-8 py-6 flex gap-6 items-center">
                                        <div className="w-16 h-20 bg-slate-50 rounded overflow-hidden flex-shrink-0 border border-slate-100">
                                            <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                                        </div>
                                        <div className="flex-grow">
                                            <div className="flex justify-between items-start">
                                                <h4 className="text-xs font-bold uppercase tracking-tight text-[#10221c]">{item.name}</h4>
                                                <p className="font-bold text-sm">₹{item.price.toLocaleString()}</p>
                                            </div>
                                            <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-widest">Size: {item.size} • Qty: {item.quantity}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Right Column: Final Summary & CTA */}
                    <aside className="w-full lg:w-[400px]">
                        <div className="sticky top-28 bg-white p-8 rounded-xl border border-slate-200 shadow-xl overflow-hidden relative">
                            {processing && (
                                <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-10 flex flex-col items-center justify-center">
                                    <div className="w-12 h-12 border-4 border-primary/20 border-t-primary rounded-full animate-spin mb-4" />
                                    <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-primary animate-pulse">Initializing Portal...</p>
                                </div>
                            )}

                            <h3 className="text-lg font-extrabold mb-6 flex items-center justify-between dark:text-black uppercase tracking-tighter">
                                Order Totals
                            </h3>

                            <div className="space-y-4 mb-10">
                                <div className="flex justify-between text-[13px] text-slate-500">
                                    <span className="font-medium">Acquisition Subtotal</span>
                                    <span className="dark:text-black font-bold text-sm">₹{checkoutTotals.subtotal.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-[13px] text-slate-500">
                                    <span className="font-medium">Global Shipment (Air)</span>
                                    <span className="text-emerald-700 font-black uppercase text-[9px] tracking-[0.2em] bg-emerald-50 px-2 py-1 rounded">Complimentary</span>
                                </div>
                                <div className="flex justify-between text-[13px] text-slate-500 border-b border-slate-50 pb-4">
                                    <span className="font-medium">Estimated Luxury Tax (8%)</span>
                                    <span className="dark:text-black font-bold text-sm">₹{checkoutTotals.tax.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-2xl font-black pt-4 text-[#10221c] items-end">
                                    <div className="flex flex-col">
                                        <span className="text-[10px] uppercase tracking-[0.3em] text-slate-400 font-bold mb-1">Total Due</span>
                                        <span className="leading-none">₹{checkoutTotals.totalAmount.toLocaleString()}</span>
                                    </div>
                                </div>
                            </div>

                            <button 
                                onClick={handlePlaceOrder}
                                disabled={processing}
                                className={`w-full py-6 rounded-lg uppercase tracking-[0.3em] text-[11px] font-black transition-all flex items-center justify-center space-x-3 shadow-lg shadow-[#10221c]/20 ${
                                    processing 
                                    ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                                    : 'bg-[#10221c] text-white hover:bg-black active:scale-95'
                                }`}
                            >
                                <span>Finalize Purchase</span>
                                <i className="material-icons text-sm">lock</i>
                            </button>

                            <p className="text-[10px] text-slate-400 text-center mt-6 font-medium italic opacity-60">
                                By placing this order, you agree to our Terms of Sale and Privacy Policy.
                            </p>
                        </div>
                    </aside>
                </div>
            </main>
            <Footer />
        </div>
    );
};

export default Checkout3;
